# Three approaches to LLM evaluation
approaches = {
    "Benchmarks":      {
        "example": "MMLU, HumanEval, GSM8K",
        "pros": "standardised, comparable",
        "cons": "can be gamed with training data",
    },
    "LLM-as-judge":    {
        "example": "GPT-4 rates Claude's output",
        "pros": "scalable, cheap",
        "cons": "position bias, self-preference bias",
    },
    "Human eval":      {
        "example": "preference studies",
        "pros": "ground truth, captures nuance",
        "cons": "expensive, slow, subjective",
    },
}

for name, info in approaches.items():
    print(f"{name}: {info['pros']}")

# Evaluation layers
def evaluation_plan():
    return [
        "1. Offline metrics (accuracy, F1, AUC)",
        "2. Benchmarks (MMLU, HumanEval)",
        "3. Adversarial testing (edge cases)",
        "4. Human review (qualitative)",
    ]

for layer in evaluation_plan():
    print(layer)

