import math

def auc_from_pairs(pos_scores, neg_scores):
    """Compute AUC as probability a random positive scores higher than a random negative."""
    wins = 0
    total = len(pos_scores) * len(neg_scores)
    for p in pos_scores:
        for n in neg_scores:
            if p > n:
                wins += 1
            elif p == n:
                wins += 0.5
    return wins / total if total else 0

pos_scores = [0.9, 0.8, 0.75, 0.6, 0.95]
neg_scores = [0.3, 0.4, 0.2, 0.5, 0.1]

print(f"AUC: {auc_from_pairs(pos_scores, neg_scores):.3f}")
